import streamlit as st
from abc import ABC, abstractmethod
from pathlib import Path
import json
import base64
import io
from PIL import Image

# ---------------------------------------------------------------------------
# Data layer
# ---------------------------------------------------------------------------

# ---------------------------------------------------------------------------
# College logo (embedded as base64 so the app is a single self-contained file)
# ---------------------------------------------------------------------------
LOGO_B64 = ""


def get_logo_image():
    return Image.open(io.BytesIO(base64.b64decode(LOGO_B64)))


database = "school_Data.json"


def load_data():
    if Path(database).exists():
        with open(database, "r") as f:
            content = f.read()
            if content:
                return json.loads(content)
    return {"students": [], "teachers": []}


def save(data):
    with open(database, "w") as f:
        json.dump(data, f, indent=4)


if "data" not in st.session_state:
    st.session_state.data = load_data()


class Person(ABC):
    @abstractmethod
    def get_role(self):
        pass

    @staticmethod
    def validate_email(email):
        return "@" in email and "." in email


class Student(Person):
    def get_role(self):
        return "student"

    # ---------------- CREATE ----------------
    def register(self, name, age, email, roll_no):
        data = st.session_state.data
        if not Person.validate_email(email):
            return False, "Invalid email address."
        for s in data["students"]:
            if s["roll_no"] == roll_no:
                return False, "A student with this roll number already exists."
        data["students"].append(
            {"name": name, "age": age, "email": email, "roll_no": roll_no, "grades": {}}
        )
        save(data)
        return True, f"Student '{name}' registered successfully."

    # ---------------- READ ----------------
    def find(self, roll_no):
        for s in st.session_state.data["students"]:
            if s["roll_no"] == roll_no:
                return s
        return None

    def all(self):
        return st.session_state.data["students"]

    # ---------------- UPDATE ----------------
    def update(self, roll_no, name=None, age=None, email=None, new_roll_no=None):
        data = st.session_state.data
        student = self.find(roll_no)
        if not student:
            return False, "Student not found."

        if new_roll_no and new_roll_no != roll_no:
            for s in data["students"]:
                if s["roll_no"] == new_roll_no:
                    return False, "A student with this new roll number already exists."

        if email is not None and email != "" and not Person.validate_email(email):
            return False, "Invalid email address."

        if name:
            student["name"] = name
        if age:
            student["age"] = age
        if email:
            student["email"] = email
        if new_roll_no:
            student["roll_no"] = new_roll_no

        save(data)
        return True, "Student updated successfully."

    def add_grade(self, roll_no, subject, marks):
        student = self.find(roll_no)
        if not student:
            return False, "Student not found."
        student["grades"][subject] = marks
        save(st.session_state.data)
        return True, "Grade added successfully."

    def update_grade(self, roll_no, subject, marks):
        student = self.find(roll_no)
        if not student:
            return False, "Student not found."
        if subject not in student["grades"]:
            return False, "This subject has no existing grade for that student."
        student["grades"][subject] = marks
        save(st.session_state.data)
        return True, "Grade updated successfully."

    def delete_grade(self, roll_no, subject):
        student = self.find(roll_no)
        if not student:
            return False, "Student not found."
        if subject not in student["grades"]:
            return False, "No grade found for that subject."
        del student["grades"][subject]
        save(st.session_state.data)
        return True, "Grade deleted successfully."

    # ---------------- DELETE ----------------
    def delete(self, roll_no):
        data = st.session_state.data
        student = self.find(roll_no)
        if not student:
            return False, "Student not found."
        data["students"].remove(student)
        save(data)
        return True, "Student deleted successfully."


class Teacher(Person):
    def get_role(self):
        return "teacher"

    # ---------------- CREATE ----------------
    def register(self, name, age, email, emp_id, subject):
        data = st.session_state.data
        if not Person.validate_email(email):
            return False, "Invalid email address."
        for t in data["teachers"]:
            if t["emp_id"] == emp_id:
                return False, "A teacher with this employee ID already exists."
        data["teachers"].append(
            {"name": name, "age": age, "email": email, "emp_id": emp_id, "subject": subject}
        )
        save(data)
        return True, f"Teacher '{name}' registered successfully."

    # ---------------- READ ----------------
    def find(self, emp_id):
        for t in st.session_state.data["teachers"]:
            if t["emp_id"] == emp_id:
                return t
        return None

    def all(self):
        return st.session_state.data["teachers"]

    # ---------------- UPDATE ----------------
    def update(self, emp_id, name=None, age=None, email=None, subject=None, new_emp_id=None):
        data = st.session_state.data
        teacher = self.find(emp_id)
        if not teacher:
            return False, "Teacher not found."

        if new_emp_id and new_emp_id != emp_id:
            for t in data["teachers"]:
                if t["emp_id"] == new_emp_id:
                    return False, "A teacher with this new employee ID already exists."

        if email is not None and email != "" and not Person.validate_email(email):
            return False, "Invalid email address."

        if name:
            teacher["name"] = name
        if age:
            teacher["age"] = age
        if email:
            teacher["email"] = email
        if subject:
            teacher["subject"] = subject
        if new_emp_id:
            teacher["emp_id"] = new_emp_id

        save(data)
        return True, "Teacher updated successfully."

    # ---------------- DELETE ----------------
    def delete(self, emp_id):
        data = st.session_state.data
        teacher = self.find(emp_id)
        if not teacher:
            return False, "Teacher not found."
        data["teachers"].remove(teacher)
        save(data)
        return True, "Teacher deleted successfully."


